SELECT plan, customer_id, DATE_FORMAT(start_date, 'yyyy-MM') AS start_month, COUNT(monthly_fee) AS monthly_fee_count, SUM(CASE WHEN status = 'PAUSED' THEN monthly_fee ELSE 0 END) AS paused_monthly_fee, SUM(CASE WHEN plan = 'standard' THEN 1 ELSE 0 END) AS standard_count FROM subscriptions WHERE end_date <= '2024-05-01' GROUP BY plan, customer_id, DATE_FORMAT(start_date, 'yyyy-MM') ORDER BY 2 DESC, paused_monthly_fee, plan, start_month LIMIT 10;
